import itertools

def solve_Sn(n):
    min_sum = float('inf')
    for p in itertools.permutations(range(1, n + 1)):
        current_sum = 0
        for i in range(n - 1):
            current_sum += 1 / (p[i] + p[i+1])
        if current_sum < min_sum:
            min_sum = current_sum
    return min_sum

